from pydantic import BaseModel
import httpx

class Donor(BaseModel):
    id: int
    email: str
    phone: str | None = None   # optional, may be null

class DonorClient:
    def __init__(self, base_url: str, timeout: float = 5.0):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get_donor(self, donor_id: int) -> Donor:
        with httpx.Client(timeout=self.timeout) as http:
            r = http.get(f'{self.base_url}/donors/{donor_id}')
        # TODO: 404 -> raise DonorNotFound(donor_id); other errors -> CrmError
        return Donor.model_validate(r.json())
